<script setup>
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import BottomNav from '@/components/common/BottomNav.vue'
import FinancialScheduleCard from '@/components/financial/FinancialScheduleCard.vue'
import { useFinancialScheduleStore } from '@/stores/financialSchedule'

const router = useRouter()
const schedule = useFinancialScheduleStore()
const tabs = [{id:'all',label:'전체'},{id:'income',label:'입금'},{id:'expense',label:'지출'}]
const notificationOpen = ref(false)
const upcomingNotifications = computed(() => schedule.notifications.filter((item) => item.date >= schedule.referenceDate))
</script>

<template><main class="page"><div class="shell">
  <header><button @click="router.back()">‹</button><h1>다가오는 금융 일정</h1><button class="bell" aria-label="알림 예정 목록" @click="notificationOpen=true">🔔<i>{{ upcomingNotifications.length }}</i></button></header>
  <section class="ticket"><div class="ticket-main"><span class="calendar">□</span><div><small>이번 달 예정</small><strong>{{ schedule.counts.all }}건</strong></div><nav><button v-for="tab in tabs" :key="tab.id" :class="{active:schedule.filter===tab.id}" @click="schedule.filter=tab.id">{{ tab.label }}</button></nav></div><div class="barcode">|||| ||| ||||</div></section>
  <div class="section-title"><h2>예정된 일정</h2><button @click="router.push('/financial-schedule/calendar')">▣ 캘린더 보기</button></div>
  <section class="list"><FinancialScheduleCard v-for="event in schedule.upcomingEvents" :key="event.id" :event="event"/><div v-if="!schedule.upcomingEvents.length" class="empty"><span>□</span><b>예정된 금융 일정이 없어요</b><small>등록한 월급과 고정지출이 이곳에 표시돼요.</small></div></section>
  <aside><span>🔔</span><div><b>일정 하루 전에 알려드려요</b><small>월급과 고정지출을 놓치지 않도록 미리 안내해 드려요.</small></div></aside>
  <div v-if="notificationOpen" class="dim" @click.self="notificationOpen=false"><section class="alert-sheet"><header><div><h2>알림 예정</h2><p>금융 일정 하루 전에 안내해 드려요.</p></div><button @click="notificationOpen=false">×</button></header><article v-for="item in upcomingNotifications" :key="item.id"><span>🔔</span><div><b>{{ item.title }}</b><small>{{ item.date }} 알림 · {{ item.message }}</small></div><em>예정</em></article><p v-if="!upcomingNotifications.length" class="no-alert">예정된 알림이 없어요.</p></section></div>
  <BottomNav />
</div></main></template>

